#include <stdlib.h>
#include <string.h>
#include <omp.h>

#define MR 6
#define NR 16
#define KCMAX 384
#define MC 72

typedef float v8 __attribute__((vector_size(32)));
typedef float v8u __attribute__((vector_size(32), aligned(4)));

static inline void kernel(int kc, const float *restrict a, const float *restrict b,
                          float *restrict C, int ldc, int mr, int nr, int first)
{
    v8 c00 = {0}, c01 = {0}, c10 = {0}, c11 = {0}, c20 = {0}, c21 = {0};
    v8 c30 = {0}, c31 = {0}, c40 = {0}, c41 = {0}, c50 = {0}, c51 = {0};

#pragma GCC unroll 4
    for (int k = 0; k < kc; k++) {
        v8 b0 = *(const v8 *)(b);
        v8 b1 = *(const v8 *)(b + 8);
        float a0 = a[0], a1 = a[1], a2 = a[2], a3 = a[3], a4 = a[4], a5 = a[5];
        c00 += a0 * b0; c01 += a0 * b1;
        c10 += a1 * b0; c11 += a1 * b1;
        c20 += a2 * b0; c21 += a2 * b1;
        c30 += a3 * b0; c31 += a3 * b1;
        c40 += a4 * b0; c41 += a4 * b1;
        c50 += a5 * b0; c51 += a5 * b1;
        a += MR;
        b += NR;
    }

    if (mr == MR && nr == NR) {
#define ST(r, x0, x1) do { \
            v8u *p0 = (v8u *)(C + (size_t)(r) * ldc); \
            v8u *p1 = (v8u *)(C + (size_t)(r) * ldc + 8); \
            if (first) { *p0 = x0; *p1 = x1; } \
            else { *p0 += x0; *p1 += x1; } \
        } while (0)
        ST(0, c00, c01); ST(1, c10, c11); ST(2, c20, c21);
        ST(3, c30, c31); ST(4, c40, c41); ST(5, c50, c51);
#undef ST
    } else {
        v8 t[MR][2] __attribute__((aligned(32)));
        t[0][0] = c00; t[0][1] = c01; t[1][0] = c10; t[1][1] = c11;
        t[2][0] = c20; t[2][1] = c21; t[3][0] = c30; t[3][1] = c31;
        t[4][0] = c40; t[4][1] = c41; t[5][0] = c50; t[5][1] = c51;
        const float *tf = (const float *)t;
        for (int i = 0; i < mr; i++) {
            float *cr = C + (size_t)i * ldc;
            const float *tr = tf + i * NR;
            if (first)
                for (int j = 0; j < nr; j++) cr[j] = tr[j];
            else
                for (int j = 0; j < nr; j++) cr[j] += tr[j];
        }
    }
}

static float *gA, *gB;
static size_t capA, capB;

static float *grow(float **p, size_t *cap, size_t nfloats)
{
    size_t bytes = (nfloats * sizeof(float) + 63) & ~(size_t)63;
    if (bytes > *cap) {
        free(*p);
        *p = (float *)aligned_alloc(64, bytes);
        *cap = bytes;
    }
    return *p;
}

/* Pack rows [i0, i0+mc) x cols [p0, p0+kc) of A into MR-row panels, zero padded. */
static void pack_a(const float *A, int n, int i0, int mc, int p0, int kc,
                   float *restrict ap)
{
    for (int ir = 0; ir < mc; ir += MR) {
        int mr = mc - ir < MR ? mc - ir : MR;
        if (mr == MR) {
            const float *s0 = A + (size_t)(i0 + ir) * n + p0;
            const float *s1 = s0 + n, *s2 = s1 + n, *s3 = s2 + n;
            const float *s4 = s3 + n, *s5 = s4 + n;
            float *d = ap;
            for (int k = 0; k < kc; k++) {
                d[0] = s0[k]; d[1] = s1[k]; d[2] = s2[k];
                d[3] = s3[k]; d[4] = s4[k]; d[5] = s5[k];
                d += MR;
            }
        } else {
            for (int k = 0; k < kc; k++)
                for (int r = 0; r < MR; r++)
                    ap[k * MR + r] = r < mr ? A[(size_t)(i0 + ir + r) * n + p0 + k] : 0.0f;
        }
        ap += (size_t)MR * kc;
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    int nkb = (n + KCMAX - 1) / KCMAX;
    int kcb = (n + nkb - 1) / nkb;
    kcb = (kcb + 7) & ~7;
    nkb = (n + kcb - 1) / kcb;

    int npB = (n + NR - 1) / NR;
    int nth = omp_get_max_threads();
    float *Bp = grow(&gB, &capB, (size_t)npB * NR * n);
    float *Abuf = grow(&gA, &capA, (size_t)nth * MC * kcb + 64);

    int nib = (n + MC - 1) / MC;
    int njc = (3 * nth + nib - 1) / nib;
    if (njc < 1) njc = 1;
    if (njc > npB) njc = npB;
    int ppc = (npB + njc - 1) / njc;
    njc = (npB + ppc - 1) / ppc;
    int ntasks = nib * njc;

    #pragma omp parallel
    {
        float *ap = Abuf + (size_t)omp_get_thread_num() * MC * kcb;

        #pragma omp for collapse(2) schedule(static)
        for (int kb = 0; kb < nkb; kb++) {
            for (int jp = 0; jp < npB; jp++) {
                int p0 = kb * kcb;
                int kc = n - p0 < kcb ? n - p0 : kcb;
                int j0 = jp * NR;
                int nr = n - j0 < NR ? n - j0 : NR;
                float *dst = Bp + (size_t)p0 * npB * NR + (size_t)jp * kc * NR;
                for (int k = 0; k < kc; k++) {
                    const float *src = B + (size_t)(p0 + k) * n + j0;
                    float *d = dst + (size_t)k * NR;
                    if (nr == NR) {
                        memcpy(d, src, NR * sizeof(float));
                    } else {
                        int j = 0;
                        for (; j < nr; j++) d[j] = src[j];
                        for (; j < NR; j++) d[j] = 0.0f;
                    }
                }
            }
        }

        #pragma omp for schedule(dynamic, 1)
        for (int t = 0; t < ntasks; t++) {
            int ib = t / njc, jc = t % njc;
            int i0 = ib * MC;
            int mc = n - i0 < MC ? n - i0 : MC;
            int jp0 = jc * ppc;
            int jp1 = jp0 + ppc < npB ? jp0 + ppc : npB;
            for (int kb = 0; kb < nkb; kb++) {
                int p0 = kb * kcb;
                int kc = n - p0 < kcb ? n - p0 : kcb;
                pack_a(A, n, i0, mc, p0, kc, ap);
                const float *bbase = Bp + (size_t)p0 * npB * NR;
                for (int jp = jp0; jp < jp1; jp++) {
                    int jj = jp * NR;
                    int nr = n - jj < NR ? n - jj : NR;
                    const float *bp = bbase + (size_t)jp * kc * NR;
                    for (int ir = 0; ir < mc; ir += MR) {
                        int mr = mc - ir < MR ? mc - ir : MR;
                        kernel(kc, ap + (size_t)ir * kc, bp,
                               C + (size_t)(i0 + ir) * n + jj, n,
                               mr, nr, kb == 0);
                    }
                }
            }
        }
    }
}
